 1	module g10_function_boundary(
 2	  input  logic [7:0] a, b, c, d,
 3	  output logic [7:0] y
 4	);
 5	  function automatic logic [7:0] sat_add(
 6	    input logic [7:0] lhs,
 7	    input logic [7:0] rhs
 8	  );
 9	    logic [8:0] wide;
10	    begin
11	      wide = lhs + rhs;
12	      sat_add = wide[8] ? 8'hff : wide[7:0];
13	    end
14	  endfunction
15	  assign y = sat_add(sat_add(sat_add(a, b), c), d);
16	endmodule
 1	module g11_one_stage_stream #(
 2	  parameter int WIDTH = 16
 3	) (
 4	  input  logic             clk,
 5	  input  logic             rst_n,
 6	  input  logic             in_valid,
 7	  output logic             in_ready,
 8	  input  logic [WIDTH-1:0] in_data,
 9	  output logic             out_valid,
10	  input  logic             out_ready,
11	  output logic [WIDTH-1:0] out_data
12	);
13	  assign in_ready = ~out_valid | out_ready;
14	  always_ff @(posedge clk or negedge rst_n) begin
15	    if (!rst_n) begin
16	      out_valid <= 1'b0;
17	      out_data <= '0;
18	    end else if (in_ready) begin
19	      out_valid <= in_valid;
20	      if (in_valid)
21	        out_data <= in_data;
22	    end
23	  end
24	endmodule
 1	module g12_two_stage_pipeline #(
 2	  parameter int WIDTH = 16
 3	) (
 4	  input  logic             clk,
 5	  input  logic             rst_n,
 6	  input  logic             valid_i,
 7	  input  logic [WIDTH-1:0] a_i, b_i, c_i,
 8	  output logic             valid_o,
 9	  output logic [WIDTH-1:0] y_o
10	);
11	  logic [WIDTH-1:0] sum_q;
12	  logic             valid_q;
13	  always_ff @(posedge clk or negedge rst_n) begin
14	    if (!rst_n) begin
15	      sum_q <= '0;
16	      valid_q <= 1'b0;
17	      y_o <= '0;
18	      valid_o <= 1'b0;
19	    end else begin
20	      sum_q <= a_i + b_i;
21	      valid_q <= valid_i;
22	      y_o <= sum_q + c_i;
23	      valid_o <= valid_q;
24	    end
25	  end
26	endmodule
